COLORS = {'confirm': (20, 20, 26), 'go': (20, 20, 26)}

def make(name, rows, c, scale=1):
    w, h = max(len(r) for r in rows), len(rows)
    im = Image.new('RGBA', (w + 2, h + 2), (0, 0, 0, 0)); p = im.load()
    pts = {(x, y) for y, r in enumerate(rows) for x, ch in enumerate(r) if ch == 'x'}
    for (x, y) in pts:
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if (x + dx, y + dy) not in pts: p[x + dx + 1, y + dy + 1] = INK + (255,)
    for (x, y) in pts: p[x + 1, y + 1] = c + (255,)
    return im

for name, rows in ICONS.items():
    make(name, rows, COLORS.get(name, IV)).save(os.path.join(OUT, f'i-{name}.png'))

# ---------------------------------------------------------------- portraits
MASKC = {'mask-mara': (84, 214, 232), 'mask-jun': (232, 112, 214), 'mask-dex': (150, 128, 255), 'mask-sol': (240, 200, 120)}
SK = [(216, 162, 122), (176, 120, 86), (120, 80, 58), (232, 190, 150)]
def portrait(skin, hair, shirt, bg, style='', accent=None):
    im = Image.new('RGB', (24, 24), bg); p = im.load()
    def r(x0, y0, x1, y1, c):
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if 0 <= x < 24 and 0 <= y < 24: p[x, y] = c
    for y in range(24):
        for x in range(24):
            if (x + y) % 2 == 0 and y > 12: p[x, y] = tuple(max(0, v - 8) for v in bg)
    s = SK[skin]; sd = tuple(int(v * 0.8) for v in s)
    r(4, 18, 19, 23, shirt); r(6, 17, 17, 17, shirt)
    r(10, 15, 13, 18, sd)
    r(7, 5, 16, 15, s); r(7, 13, 16, 15, sd); r(6, 8, 6, 11, sd); r(17, 8, 17, 11, sd)
    r(9, 9, 10, 9, (30, 24, 28)); r(13, 9, 14, 9, (30, 24, 28))
    r(9, 8, 10, 8, tuple(int(v * 0.6) for v in hair)); r(13, 8, 14, 8, tuple(int(v * 0.6) for v in hair))
    r(11, 12, 12, 12, sd); r(10, 14, 13, 14, (150, 80, 80) if skin != 2 else (100, 50, 50))
    if style == 'long': r(6, 3, 17, 6, hair); r(5, 5, 6, 17, hair); r(17, 5, 18, 17, hair)
    elif style == 'bun': r(7, 3, 16, 6, hair); r(10, 1, 13, 3, hair)
    elif style == 'buzz': r(7, 4, 16, 6, hair)
    elif style == 'bald': r(7, 4, 16, 5, sd)
    elif style == 'cap': r(6, 3, 17, 6, (24, 34, 64)); r(5, 6, 18, 7, (18, 26, 50)); r(11, 4, 12, 5, (226, 194, 80))
    elif style == 'police': r(6, 3, 17, 6, (20, 30, 70)); r(5, 6, 18, 7, (14, 22, 54)); r(11, 4, 12, 5, (226, 194, 80))
    elif style == 'helmet': r(5, 2, 18, 8, (40, 44, 50)); r(7, 8, 16, 10, (20, 22, 26)); r(8, 9, 15, 9, (70, 90, 110))
    elif style.startswith('mask'):
        mc = MASKC[style]
        r(7, 2, 16, 4, hair); r(6, 4, 17, 16, (226, 220, 206)); r(6, 7, 17, 11, mc)
        r(8, 8, 10, 10, (20, 18, 24)); r(13, 8, 15, 10, (20, 18, 24)); r(9, 14, 14, 14, tuple(int(v * 0.6) for v in mc)); r(11, 5, 12, 6, (200, 190, 170))
    else: r(7, 3, 16, 6, hair); r(6, 5, 6, 8, hair); r(17, 5, 17, 8, hair)
    if accent: r(4, 18, 5, 23, accent); r(18, 18, 19, 23, accent)
    if style in ('cap', 'police'): r(9, 19, 10, 20, (226, 194, 80))
    return im

